-- Generated by tools/bundle.lua from src/. Do not edit.
local uz = uz or fb  -- Uzume < 0.22 only has the old name fb
local __mod = {}
local __loaded = {}
local function require(name)
  local m = __loaded[name]
  if m ~= nil then
    if m == __loaded then return nil end
    return m
  end
  local f = __mod[name]
  if not f then return nil end
  __loaded[name] = __loaded -- cycle guard
  local r = f(name)
  if r == nil then r = true end
  __loaded[name] = r
  return r
end
__mod["census"] = function(...)
-- Counting owned Pokemon per species/form (team and boxes) to see whether a wild encounter was caught.
-- A census is a job that reads the team at once and then one box per step, so the core is never asked for
-- many boxes in one tick. Without box support the census covers the team only.
local data = require("data")

local M = {}
M.__index = M

local function add(counts, rec)
  if type(rec) == "table" and math.type(rec.species) == "integer" and rec.species >= 1 and rec.egg ~= true then
    local key = data.species_key(rec.species, math.type(rec.form) == "integer" and rec.form or 0)
    counts[key] = (counts[key] or 0) + 1
  end
end

local function add_list(counts, list)
  if type(list) ~= "table" then return end
  for _, rec in pairs(list) do add(counts, rec) end
end

function M.new(core)
  return setmetatable({ core = core, counts = {}, next_box = 1, boxes = nil, started = false, boxed = false }, M)
end

--- One step. Returns true when the census is complete.
function M:step()
  if not self.started then
    self.started = true
    local team = self.core:team()
    if not team then
      self.failed = true
      return true
    end
    add_list(self.counts, team)
    self.boxes = self.core:box_count()
    self.boxed = self.boxes ~= nil
    return not self.boxes or self.boxes < 1
  end
  local list = self.core:box(self.next_box)
  if list then add_list(self.counts, list) end
  self.next_box = self.next_box + 1
  return self.next_box > self.boxes
end

--- Catch detection around one wild battle: a census before it starts and one or more after it ended.
local Catch = {}
Catch.__index = Catch
M.Catch = Catch

local PASSES = { 0, 4000, 12000 } -- ms after the battle ended; the game adds a caught creature late

function Catch.new(core)
  return setmetatable({ core = core, job = nil, cur = nil }, Catch)
end

--- foes: list of { zone, species, form }.
function Catch:battle_started(foes)
  self.cur = { foes = foes, before = nil, ended = false, pass = 1 }
  self.job = { census = M.new(self.core), purpose = "before" }
end

function Catch:battle_ended(now)
  local cur = self.cur
  if not cur then return end
  cur.ended = true
  cur.at = now
end

--- One step; returns a list of { zone, species, form } that were caught.
function Catch:tick(now)
  local out = {}
  local cur = self.cur
  if self.job then
    if self.job.census:step() then
      local job = self.job
      self.job = nil
      if not cur then return out end
      if job.purpose == "before" then
        if not job.census.failed then cur.before = job.census.counts end
      else
        local remaining = {}
        for _, f in ipairs(cur.foes) do
          local key = data.species_key(f.species, f.form)
          if (job.census.counts[key] or 0) > (cur.before[key] or 0) then
            out[#out + 1] = f
          else
            remaining[#remaining + 1] = f
          end
        end
        cur.foes = remaining
        cur.pass = cur.pass + 1
        if #remaining == 0 or cur.pass > #PASSES then self.cur = nil end
      end
    end
  elseif cur and cur.ended then
    if not cur.before then
      self.cur = nil -- the census before the battle never finished: no way to tell, so no guess
    elseif now >= cur.at + PASSES[cur.pass] then
      self.job = { census = M.new(self.core), purpose = "after" }
    end
  end
  return out
end

--- True while a battle is being watched for a catch.
function Catch:active() return self.cur ~= nil end

return M

end
__mod["corelink"] = function(...)
-- Reads the Pokemon core interface (`pokemon.core` of uzume.soullink-core) through uz.call.
-- Every call is protected; failures and "not ready" answers come back as nil and are never cached,
-- so names and types appear as soon as the game text is loaded. All ids are the game's; names are read
-- at runtime and kept in memory only.
local M = {}
M.__index = M

local INTERFACE = "pokemon.core"

function M.new(uz)
  return setmetatable({ uz = uz, names = {}, types = {}, zone_names = {}, universe = nil, warned = false }, M)
end

--- Calls a function of the interface. Returns value, or nil, reason.
function M:call(fn, ...)
  local ok, v, why = pcall(self.uz.call, INTERFACE, fn, ...)
  if not ok then
    if not self.warned then
      self.warned = true
      self.uz.log.warn("pokemon.core call failed: " .. tostring(v))
    end
    return nil, "unavailable"
  end
  if v == nil then return nil, why or "unavailable" end
  return v
end

function M:location() 
  local loc = self:call("location")
  if type(loc) == "table" and math.type(loc.zone) == "integer" then return loc end
  return nil
end

function M:encounters()
  local list = self:call("encounters")
  return type(list) == "table" and list or nil
end

function M:battle()
  local b = self:call("battle")
  return type(b) == "table" and b or nil
end

function M:team()
  local t = self:call("team")
  return type(t) == "table" and t or nil
end

function M:box_count()
  local n = self:call("box_count")
  return math.type(n) == "integer" and n or nil
end

function M:box(n)
  local b = self:call("box", n)
  return type(b) == "table" and b or nil
end

--- A name from the game text, or nil while it is not available.
function M:name(kind, id)
  local key = kind .. ":" .. tostring(id)
  local cached = self.names[key]
  if cached then return cached end
  local v = self:call("name", kind, id)
  if type(v) == "string" and v ~= "" then
    self.names[key] = v
    return v
  end
  return nil
end

--- Type ids of a species/form as a list of one or two ids, or nil while unknown.
function M:species_types(species, form)
  local key = species .. ":" .. (form or 0)
  local cached = self.types[key]
  if cached then return cached end
  local info = self:call("species_info", species, form or 0)
  if type(info) == "table" and type(info.types) == "table" and math.type(info.types[1]) == "integer" then
    local t = { info.types[1] }
    if math.type(info.types[2]) == "integer" and info.types[2] ~= info.types[1] then t[2] = info.types[2] end
    self.types[key] = t
    return t
  end
  return nil
end

--- Area (location) universe in game order: list of { zone, name } for every zone with wild encounters.
function M:zone_list()
  if self.universe then return self.universe end
  local areas = self:call("areas")
  if type(areas) ~= "table" or #areas == 0 then return nil end
  local out, seen = {}, {}
  for _, a in ipairs(areas) do
    for _, z in ipairs(a.zones or {}) do
      if math.type(z) == "integer" and not seen[z] then
        seen[z] = true
        out[#out + 1] = { zone = z, name = type(a.name) == "string" and a.name or nil }
        if type(a.name) == "string" then self.zone_names[z] = a.name end
      end
    end
  end
  self.universe = out
  return out
end

--- Name of a zone (its location name), or nil while unknown.
function M:zone_name(zone)
  local cached = self.zone_names[zone]
  if cached then return cached end
  local info = self:call("zone_info", zone)
  if type(info) == "table" and type(info.name) == "string" and info.name ~= "" then
    self.zone_names[zone] = info.name
    return info.name
  end
  return nil
end

--- Remembers a name the core reported with an event or a location read.
function M:remember_zone(zone, name)
  if type(name) == "string" and name ~= "" then self.zone_names[zone] = name end
end

return M

end
__mod["data"] = function(...)
-- What the player has seen, per area. Pure data logic, keyed by ids only (no names are stored).
--
-- data = { v = 1, areas = { ["z<zone>"] = area } }
-- area = { zone, visited, notes, wild = { ["s<species>f<form>"] = entry }, trainers = { same keys = entry } }
-- entry = { species, form, n = times seen, caught = bool (wild only), shiny = bool (wild only) }
local util = require("util")

local M = {}
M.MAX_AREAS = 1000
M.MAX_SPECIES = 200
M.MAX_NOTE = 2000

local function is_int(v) return math.type(v) == "integer" end

function M.new() return { v = 1, areas = {} } end

function M.area_key(zone) return "z" .. zone end
function M.species_key(species, form) return "s" .. species .. "f" .. (form or 0) end

--- The area of a zone; created when `create` is true (nil when the area limit is reached).
function M.area(data, zone, create)
  local key = M.area_key(zone)
  local a = data.areas[key]
  if a or not create then return a end
  local count = 0
  for _ in pairs(data.areas) do count = count + 1 end
  if count >= M.MAX_AREAS then return nil end
  a = { zone = zone, visited = false, notes = "", wild = {}, trainers = {} }
  data.areas[key] = a
  return a
end

local function count(t)
  local n = 0
  for _ in pairs(t) do n = n + 1 end
  return n
end

--- Marks an area as visited. Returns true when that changed something.
function M.visit(data, zone)
  local a = M.area(data, zone, true)
  if not a or a.visited then return false end
  a.visited = true
  return true
end

local function record(data, zone, kind, species, form, shiny)
  if not is_int(zone) or not is_int(species) or species < 1 then return false end
  form = is_int(form) and form >= 0 and form or 0
  local a = M.area(data, zone, true)
  if not a then return false end
  a.visited = true
  local key = M.species_key(species, form)
  local e = a[kind][key]
  if not e then
    if count(a[kind]) >= M.MAX_SPECIES then return false end
    e = { species = species, form = form, n = 0 }
    if kind == "wild" then e.caught, e.shiny = false, false end
    a[kind][key] = e
  end
  e.n = e.n + 1
  if kind == "wild" and shiny then e.shiny = true end
  return true
end

--- A wild encounter of a species in a zone. Returns true when recorded.
function M.record_wild(data, zone, species, form, shiny)
  return record(data, zone, "wild", species, form, shiny)
end

--- A species seen on a trainer's side in a zone (once per battle).
function M.record_trainer(data, zone, species, form)
  return record(data, zone, "trainers", species, form)
end

--- Marks a wild species of an area as caught. Returns true when that changed something.
function M.mark_caught(data, zone, species, form)
  local a = M.area(data, zone, false)
  local e = a and a.wild[M.species_key(species, form)]
  if not e or e.caught then return false end
  e.caught = true
  return true
end

--- Free-text note of an area (cleared notes of unknown areas are not created).
function M.set_note(data, zone, text)
  text = tostring(text or "")
  if #text > M.MAX_NOTE then
    local cut = utf8.offset(text, M.MAX_NOTE + 1) or (M.MAX_NOTE + 1)
    text = text:sub(1, math.min(cut - 1, M.MAX_NOTE))
  end
  local a = M.area(data, zone, text ~= "")
  if not a then return false end
  a.notes = text
  return true
end

--- Number of seen wild species, caught ones and trainer species of an area.
function M.counts(area)
  local seen, caught = 0, 0
  for _, e in pairs(area.wild) do
    seen = seen + 1
    if e.caught then caught = caught + 1 end
  end
  return seen, caught, count(area.trainers)
end

--- Every species seen anywhere (wild or on a trainer), as key -> { species, form }.
function M.seen_species(data)
  local out = {}
  for _, a in pairs(data.areas) do
    for _, kind in ipairs({ "wild", "trainers" }) do
      for key, e in pairs(a[kind]) do out[key] = { species = e.species, form = e.form } end
    end
  end
  return out
end

--- Validates stored data; returns a clean copy or nil when it is not tracker data.
function M.sanitize(v)
  if type(v) ~= "table" or v.v ~= 1 or type(v.areas) ~= "table" then return nil end
  local data = M.new()
  local n = 0
  for _, a in pairs(v.areas) do
    if type(a) == "table" and is_int(a.zone) and a.zone >= 0 and n < M.MAX_AREAS then
      local area = M.area(data, a.zone, true)
      n = n + 1
      area.visited = a.visited == true
      area.notes = type(a.notes) == "string" and a.notes:sub(1, M.MAX_NOTE) or ""
      for _, kind in ipairs({ "wild", "trainers" }) do
        if type(a[kind]) == "table" then
          for _, e in pairs(a[kind]) do
            if type(e) == "table" and is_int(e.species) and e.species >= 1 then
              local form = is_int(e.form) and e.form >= 0 and e.form or 0
              local clean = { species = e.species, form = form, n = is_int(e.n) and e.n >= 1 and e.n or 1 }
              if kind == "wild" then clean.caught, clean.shiny = e.caught == true, e.shiny == true end
              if count(area[kind]) < M.MAX_SPECIES then area[kind][M.species_key(e.species, form)] = clean end
            end
          end
        end
      end
    end
  end
  return data
end

--- True when the area has anything the player recorded.
function M.has_data(area)
  return area.visited or area.notes ~= "" or next(area.wild) ~= nil or next(area.trainers) ~= nil
end


local function merge_notes(a, b)
  if a == b or b == "" then return a end
  if a == "" then return b end
  if a:find(b, 1, true) then return a end
  if b:find(a, 1, true) then return b end
  local joined = a .. "\n---\n" .. b
  if #joined > M.MAX_NOTE then joined = joined:sub(1, M.MAX_NOTE) end
  return joined
end

--- Merges two data sets without losing anything either side recorded (union of areas and species, larger
--- counts, caught/visited/shiny if either says so, both notes when they differ). Returns a new data table.
function M.merge(a, b)
  local out = M.sanitize(a) or M.new()
  local other = M.sanitize(b) or M.new()
  for _, oa in pairs(other.areas) do
    local area = M.area(out, oa.zone, true)
    if area then
      area.visited = area.visited or oa.visited
      area.notes = merge_notes(area.notes, oa.notes)
      for _, kind in ipairs({ "wild", "trainers" }) do
        for key, e in pairs(oa[kind]) do
          local mine = area[kind][key]
          if not mine then
            if count(area[kind]) < M.MAX_SPECIES then area[kind][key] = util.copy(e) end
          else
            mine.n = math.max(mine.n, e.n)
            if kind == "wild" then
              mine.caught = mine.caught or e.caught
              mine.shiny = mine.shiny or e.shiny
            end
          end
        end
      end
    end
  end
  return out
end

M.copy = util.copy

return M

end
__mod["main"] = function(...)
-- Entry module of the Randomizer Tracker plugin.
local Tracker = require("tracker")

uz.log.info(uz.i18n.t("loaded", { version = (uz.plugin and uz.plugin.version) or "?" }))
Tracker.new(uz):start()

end
__mod["tracker"] = function(...)
-- Wires the seen-data to Uzume: polls pokemon.core, stores per run or game, builds the views.
local census = require("census")
local corelink = require("corelink")
local data = require("data")
local util = require("util")
local views = require("views")

local Tracker = {}
Tracker.__index = Tracker

local CORE_ID = "uzume.soullink-core"
local POLL_TICKS = 10        -- poll the core about 3 times per second at 30 ticks per second
local SAVE_DELAY_MS = 2000   -- changes are written at most this often
local RENDER_MS = 500        -- views are rebuilt at most this often
local RETRY_NAMES_MS = 5000  -- rebuild views while names or types are still missing
local TYPING_QUIET_MS = 3000 -- no redraw right after the person typed a note
local MAX_ROWS = 500

--- Store key: "tracker.run-<run id>" in a run, else "tracker.game-<game code>"; nil without either.
function Tracker.store_key(uz)
  local function clean(s, max)
    return (tostring(s):lower():gsub("[^a-z0-9_.-]", "_")):sub(1, max)
  end
  if uz.run and uz.run.current then
    local ok, cur = pcall(uz.run.current)
    if ok and type(cur) == "table" and cur.id ~= nil and tostring(cur.id) ~= "" then
      return "tracker.run-" .. clean(cur.id, 36)
    end
  end
  local code = uz.game and uz.game.code
  if type(code) == "string" and code ~= "" then return "tracker.game-" .. clean(code, 40) end
  return nil
end

function Tracker.new(uz)
  local self = setmetatable({}, Tracker)
  self.uz = uz
  self.T = function(key, vars) return uz.i18n.t(key, vars) end
  self.core = corelink.new(uz)
  self.catch = census.Catch.new(self.core)
  self.ticks = 0
  self.rev = 0
  self.last_seq = 0
  self.filter = "all"
  self.shown = {}
  self.last_save, self.last_render, self.quiet_until, self.last_retry = 0, 0, 0, 0
  return self
end

-- Storage -------------------------------------------------------------------------------------------------

function Tracker:load()
  self.data, self.rev = data.new(), 0
  if not self.key or not self.uz.store then return end
  local ok, v, rev = pcall(self.uz.store.get, self.key)
  if not ok then
    self.uz.log.warn("store.get failed: " .. tostring(v))
    return
  end
  self.rev = rev or 0
  self.data = data.sanitize(v) or data.new()
end

function Tracker:notify(title, body)
  pcall(self.uz.ui.notify, { tone = "warning", title = title, text = body })
end

--- Writes the data. On a stale write the stored version is merged with ours (nothing is lost) and written again.
function Tracker:save()
  self.dirty = false
  self.last_save = self.uz.clock()
  if not self.key or not self.uz.store then return end
  for attempt = 1, 2 do
    local ok, res, why = pcall(self.uz.store.put, self.key, self.data, self.rev)
    if not ok then
      self.uz.log.warn("store.put failed: " .. tostring(res))
      self.dirty = true
      return
    elseif res == true then
      self.rev = why
      return
    elseif why == "conflict" and attempt == 1 then
      local gok, remote, rev = pcall(self.uz.store.get, self.key)
      if not gok then
        self.dirty = true
        return
      end
      self.data = data.merge(remote, self.data)
      self.rev = rev or 0
      self.view_dirty = true
    else
      self.uz.log.warn("store.put refused: " .. tostring(why))
      self.dirty = true
      self:notify(self.T("store.failed.title"), self.T("store.failed.text"))
      return
    end
  end
end

--- The stored version changed elsewhere: merge it into ours.
function Tracker:on_store_changed()
  if not self.key or not self.uz.store then return end
  local ok, remote, rev = pcall(self.uz.store.get, self.key)
  if not ok or remote == nil then return end
  self.data = data.merge(remote, self.data)
  self.rev = rev or self.rev
  self.dirty, self.view_dirty = true, true
end

-- Lifecycle -----------------------------------------------------------------------------------------------

function Tracker:start()
  local uz = self.uz
  self.key = Tracker.store_key(uz)
  self:load()
  uz.on_tick(function() self:tick() end)
  uz.ui.on_action(function(a, v) self:action(a, v) end)
  for _, name in ipairs({ "encounter", "location.changed", "battle.started", "battle.ended" }) do
    uz.events.on(CORE_ID, name, function() self:poll() end)
  end
  uz.events.on("app", "store.changed", function(k)
    if k == self.key then self:on_store_changed() end
  end)
  uz.events.on("app", "store.conflict", function(k)
    if k == self.key then self.dirty = true end
  end)
  self.view_dirty = true
  self:render_all()
end

-- Polling the core ----------------------------------------------------------------------------------------

function Tracker:mark(changed)
  if changed then
    self.dirty, self.view_dirty = true, true
  end
end

function Tracker:poll_location()
  local loc = self.core:location()
  if not loc then return end
  self.core:remember_zone(loc.zone, loc.name)
  if loc.zone ~= self.cur_zone then
    self.cur_zone = loc.zone
    self.view_dirty = true
    if data.visit(self.data, loc.zone) then self.dirty = true end
  end
end

function Tracker:poll_encounters()
  local list = self.core:encounters()
  if not list then return end
  for _, e in ipairs(list) do
    if math.type(e.seq) == "integer" and e.seq > self.last_seq then
      self.last_seq = e.seq
      local zone = math.type(e.zone) == "integer" and e.zone or self.cur_zone
      if zone and math.type(e.species) == "integer" then
        self:mark(data.record_wild(self.data, zone, e.species, e.form, e.shiny == true))
      end
    end
  end
end

function Tracker:poll_battle()
  local b = self.core:battle()
  local active = b and b.active == true
  local now = self.uz.clock()
  if active and not self.battle then
    self.battle = { kind = b.kind, seen = {} }
    if b.kind == "wild" and self.cur_zone then
      local foes = {}
      for _, f in ipairs(b.foes or {}) do
        if math.type(f.species) == "integer" and f.species >= 1 then
          foes[#foes + 1] = { zone = self.cur_zone, species = f.species, form = math.type(f.form) == "integer" and f.form or 0 }
        end
      end
      self.catch:battle_started(foes)
    end
  end
  if active and self.battle.kind == "trainer" and self.cur_zone then
    for _, f in ipairs(b.foes or {}) do
      if math.type(f.species) == "integer" and f.species >= 1 then
        local key = data.species_key(f.species, f.form)
        if not self.battle.seen[key] then
          self.battle.seen[key] = true
          self:mark(data.record_trainer(self.data, self.cur_zone, f.species, f.form))
        end
      end
    end
  end
  if not active and self.battle then
    if self.battle.kind == "wild" then self.catch:battle_ended(now) end
    self.battle = nil
  end
end

function Tracker:poll()
  self:poll_location()
  self:poll_encounters()
  self:poll_battle()
end

function Tracker:tick()
  self.ticks = self.ticks + 1
  local now = self.uz.clock()
  if self.ticks % POLL_TICKS == 0 then self:poll() end
  if self.catch:active() then
    for _, f in ipairs(self.catch:tick(now)) do
      self:mark(data.mark_caught(self.data, f.zone, f.species, f.form))
    end
  end
  if self.dirty and now - self.last_save >= SAVE_DELAY_MS then self:save() end
  if self.unresolved and now - self.last_retry >= RETRY_NAMES_MS then
    self.last_retry = now
    self.view_dirty = true
  end
  if self.view_dirty and now >= self.quiet_until and now - self.last_render >= RENDER_MS then
    self:render_all()
  end
end

-- View model ----------------------------------------------------------------------------------------------

function Tracker:zone_label(zone)
  local name = self.core:zone_name(zone)
  if name then return name end
  self.unresolved = true
  return self.T("area.zone", { zone = zone })
end

function Tracker:entry_view(key, e)
  local v = { key = key, species = e.species, form = e.form, n = e.n, caught = e.caught, shiny = e.shiny }
  v.name = self.core:name("species", e.species)
  if not v.name then
    self.unresolved = true
    v.name = self.T("species.unknown", { id = e.species })
  end
  local types = self.core:species_types(e.species, e.form)
  if types then
    local names = {}
    for _, id in ipairs(types) do
      local n = self.core:name("type", id)
      if not n then self.unresolved = true; n = self.T("types.unknown", { id = id }) end
      names[#names + 1] = n
    end
    v.types = table.concat(names, " / ")
  end
  return v
end

local function sorted_entries(self, map)
  local list = {}
  for key, e in pairs(map) do list[#list + 1] = self:entry_view(key, e) end
  table.sort(list, function(a, b)
    if a.species ~= b.species then return a.species < b.species end
    return a.form < b.form
  end)
  return list
end

function Tracker:area_view(zone)
  local a = data.area(self.data, zone, false) or { visited = false, notes = "", wild = {}, trainers = {} }
  return { zone = zone, name = self:zone_label(zone), visited = a.visited, notes = a.notes,
    wild = sorted_entries(self, a.wild), trainers = sorted_entries(self, a.trainers) }
end

--- Seen types overview over the whole scope: type name and number of seen species with it.
function Tracker:types_view()
  local counts, pending = {}, 0
  for _, s in pairs(data.seen_species(self.data)) do
    local types = self.core:species_types(s.species, s.form)
    if types then
      for _, id in ipairs(types) do counts[id] = (counts[id] or 0) + 1 end
    else
      pending = pending + 1
    end
  end
  local list = {}
  for id, n in pairs(counts) do
    local name = self.core:name("type", id)
    if not name then self.unresolved = true; name = self.T("types.unknown", { id = id }) end
    list[#list + 1] = { id = id, name = name, n = n }
  end
  table.sort(list, function(a, b)
    if a.n ~= b.n then return a.n > b.n end
    return a.id < b.id
  end)
  if pending > 0 then self.unresolved = true end
  return list, pending
end

--- Rows of the all-areas table: the core's encounter areas in game order, then other areas with data.
function Tracker:rows_view()
  local zones, seen = {}, {}
  for _, z in ipairs(self.core:zone_list() or {}) do
    if not seen[z.zone] then seen[z.zone] = true; zones[#zones + 1] = z.zone end
  end
  local extra = {}
  for _, a in pairs(self.data.areas) do
    if not seen[a.zone] and data.has_data(a) then extra[#extra + 1] = a.zone end
  end
  table.sort(extra)
  for _, z in ipairs(extra) do zones[#zones + 1] = z end

  local rows, names = {}, {}
  for _, zone in ipairs(zones) do
    local a = data.area(self.data, zone, false)
    local visited = a ~= nil and a.visited
    local has_notes = a ~= nil and a.notes ~= ""
    local f = self.filter
    if f == "all" or (f == "unvisited" and not visited) or (f == "visited" and visited) or (f == "notes" and has_notes) then
      local seen_n, caught_n, trainers_n = 0, 0, 0
      if a then seen_n, caught_n, trainers_n = data.counts(a) end
      local name = self:zone_label(zone)
      names[name] = (names[name] or 0) + 1
      rows[#rows + 1] = { zone = zone, name = name, seen = seen_n, caught = caught_n, trainers = trainers_n, notes = has_notes }
    end
  end
  for _, r in ipairs(rows) do
    if names[r.name] > 1 then r.name = self.T("area.zone_suffix", { name = r.name, zone = r.zone }) end
  end
  local truncated = #rows > MAX_ROWS
  while #rows > MAX_ROWS do rows[#rows] = nil end
  return rows, truncated
end

function Tracker:vm(with_rows)
  self.unresolved = false
  local vm = { ready = self.key ~= nil, filter = self.filter, rows = {}, types = {}, types_pending = 0 }
  if not vm.ready then return vm end
  if self.cur_zone then vm.cur = self:area_view(self.cur_zone) end
  vm.types, vm.types_pending = self:types_view()
  if with_rows then
    vm.rows, vm.truncated = self:rows_view()
    local sel = self.selected_zone or self.cur_zone
    if sel then vm.selected = self:area_view(sel) end
  end
  return vm
end

-- Rendering -----------------------------------------------------------------------------------------------

function Tracker:set_if_changed(slot, tree)
  local key = util.ser(tree)
  if self.shown[slot] == key then return end
  self.shown[slot] = key
  self.uz.ui.set(slot, tree)
end

function Tracker:render_all()
  self.view_dirty = false
  self.last_render = self.uz.clock()
  self:set_if_changed("panel", views.panel(self:vm(false), self.T))
  self:set_if_changed("screen", views.screen(self:vm(true), self.T))
end

-- Actions -------------------------------------------------------------------------------------------------

local H = {}

function H.open(self)
  if self.uz.ui.open then self.uz.ui.open("screen") end
end

function H.pick(self, v)
  if math.type(v) == "integer" then
    self.selected_zone = v
    self.view_dirty = true
  end
end

function Tracker:action(action, value)
  if not self.key then return end
  local h = H[action]
  if h then
    h(self, value)
    self:render_all()
    return
  end
  local filter = tostring(action):match("^filter:(%a+)$")
  if filter then
    for _, f in ipairs(views.FILTERS) do
      if f == filter then
        self.filter = f
        self:render_all()
      end
    end
    return
  end
  local zone = tostring(action):match("^note:(%d+)$")
  if zone then
    if data.set_note(self.data, tonumber(zone), value) then
      self:save()
      self.quiet_until = self.uz.clock() + TYPING_QUIET_MS
      self.view_dirty = true
    end
  end
end

return Tracker

end
__mod["util"] = function(...)
-- Small helpers shared by the modules.
local M = {}

function M.copy(v)
  if type(v) ~= "table" then return v end
  local c = {}
  for k, x in pairs(v) do c[k] = M.copy(x) end
  return c
end

function M.trim(s)
  return (tostring(s):match("^%s*(.-)%s*$"))
end

--- Split name: control characters become spaces, "|" becomes "/" (the text format uses "|"), trimmed, at most
--- `max` characters (default 60). Returns "" for empty input.
function M.clean_name(s, max)
  max = max or 60
  s = tostring(s or "")
  s = s:gsub("|", "/")
  s = s:gsub("%c", " ")
  s = M.trim(s)
  s = s:gsub("%s+", " ")
  local len = utf8.len(s)
  if len and len > max then
    s = s:sub(1, utf8.offset(s, max + 1) - 1)
  elseif not len and #s > max then
    s = s:sub(1, max)
  end
  return s
end

--- Deterministic string form of a value (sorted keys), to compare trees and states cheaply.
function M.ser(v)
  local tv = type(v)
  if tv == "table" then
    local keys = {}
    for k in pairs(v) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local out = {}
    for _, k in ipairs(keys) do out[#out + 1] = tostring(k) .. "=" .. M.ser(v[k]) end
    return "{" .. table.concat(out, ",") .. "}"
  elseif tv == "string" then
    return string.format("%q", v)
  end
  return tostring(v)
end

return M

end
__mod["views"] = function(...)
-- Declarative UI trees (panel, screen) from a view model. Pure functions, no uz access.
local M = {}

local function text(props)
  props.type = "text"
  return props
end

local function species_title(e, T)
  if e.form and e.form > 0 then return T("species.form", { name = e.name, form = e.form }) end
  return e.name
end

local function species_rows(entries, T, wild)
  local rows = {}
  for _, e in ipairs(entries) do
    local meta
    if wild then
      meta = e.caught and T("row.caught") or T("row.seen", { n = e.n })
    else
      meta = T("row.seen", { n = e.n })
    end
    local row = { id = e.key, title = species_title(e, T), meta = meta, tone = (wild and e.caught) and "ok" or "neutral" }
    if e.types and e.types ~= "" then row.sub = e.types end
    rows[#rows + 1] = row
  end
  return rows
end

--- Section for one area: wild species, trainer species and the notes field.
function M.area_section(a, T, id_prefix)
  local kids = {}
  if a.visited then
    kids[#kids + 1] = { type = "badge", text = T("area.visited"), tone = "ok" }
  else
    kids[#kids + 1] = { type = "badge", text = T("area.not_visited"), tone = "neutral" }
  end
  if #a.wild > 0 then
    kids[#kids + 1] = text({ text = T("area.wild"), style = "eyebrow" })
    kids[#kids + 1] = { type = "list", id = id_prefix .. "wild", rows = species_rows(a.wild, T, true) }
  else
    kids[#kids + 1] = text({ text = T("area.no_wild"), style = "meta" })
  end
  if #a.trainers > 0 then
    kids[#kids + 1] = text({ text = T("area.trainers"), style = "eyebrow" })
    kids[#kids + 1] = { type = "list", id = id_prefix .. "trainers", rows = species_rows(a.trainers, T, false) }
  end
  kids[#kids + 1] = text({ text = T("area.notes"), style = "eyebrow" })
  kids[#kids + 1] = { type = "textarea", id = id_prefix .. "notes", action = "note:" .. a.zone, value = a.notes,
    lines = 4, placeholder = T("area.notes.placeholder") }
  return { type = "section", id = id_prefix .. "area", title = a.name, children = kids }
end

local function types_section(vm, T, id)
  local kids
  if #vm.types == 0 then
    kids = { text({ text = T("types.none"), style = "meta" }) }
  else
    local chips = {}
    for _, ty in ipairs(vm.types) do
      chips[#chips + 1] = { type = "chip", text = T("types.chip", { name = ty.name, n = ty.n }) }
    end
    kids = { { type = "grid", gap = 8, columns = 2, children = chips } }
    if vm.types_pending > 0 then
      kids[#kids + 1] = text({ text = T("types.pending", { n = vm.types_pending }), style = "meta" })
    end
  end
  return { type = "section", id = id, title = T("types.title"), children = kids }
end

function M.panel(vm, T)
  if not vm.ready then
    return { type = "empty", title = T("empty.no_game.title"), text = T("empty.no_game.text") }
  end
  local kids = {}
  if vm.cur then
    kids[#kids + 1] = M.area_section(vm.cur, T, "p_")
  else
    kids[#kids + 1] = { type = "empty", title = T("empty.waiting.title"), text = T("empty.waiting.text") }
  end
  kids[#kids + 1] = types_section(vm, T, "p_types")
  kids[#kids + 1] = { type = "button", id = "p_all", label = T("btn.all_areas"), action = "open", variant = "secondary" }
  return { type = "column", gap = 12, children = kids }
end

local FILTERS = { "all", "unvisited", "visited", "notes" }
M.FILTERS = FILTERS

function M.screen(vm, T)
  if not vm.ready then
    return { type = "empty", title = T("empty.no_game.title"), text = T("empty.no_game.text") }
  end
  local chips = {}
  for _, f in ipairs(FILTERS) do
    chips[#chips + 1] = { type = "chip", id = "f_" .. f, text = T("filter." .. f), action = "filter:" .. f, selected = vm.filter == f }
  end
  local rows = {}
  for _, r in ipairs(vm.rows) do
    rows[#rows + 1] = { cells = { r.name, tostring(r.seen), tostring(r.caught), tostring(r.trainers), r.notes and T("col.yes") or "" },
      action = "pick", value = r.zone }
  end
  local kids = {
    { type = "row", gap = 8, align = "center", children = chips },
  }
  if #rows == 0 then
    kids[#kids + 1] = { type = "empty", title = T("empty.no_rows.title"), text = T("empty.no_rows.text") }
  else
    kids[#kids + 1] = { type = "table", id = "areas",
      columns = { T("col.area"), T("col.seen"), T("col.caught"), T("col.trainers"), T("col.notes") }, rows = rows }
    if vm.truncated then
      kids[#kids + 1] = text({ text = T("rows.truncated", { n = #rows }), style = "meta" })
    end
  end
  if vm.selected then kids[#kids + 1] = M.area_section(vm.selected, T, "s_") end
  kids[#kids + 1] = types_section(vm, T, "s_types")
  return { type = "column", gap = 16, children = kids }
end

return M

end
require("main")
